result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/lissajous.js", "content": "import * as THREE from 'three';

/**
 * Curve following a 3D Lissajous figure:
 *   x(t) = scale * sin(a * 2π * t + delta)
 *   y(t) = scale * sin(b * 2π * t)
 *   z(t) = scale * sin((a + b) * π * t)
 *
 * For integer a and b the curve is closed: getPoint(0) === getPoint(1).
 */
export function lissajousCurve({ a = 3, b = 2, delta = Math.PI / 2, scale = 1 } = {}) {
  const TAU = Math.PI * 2;

  class LissajousCurve extends THREE.Curve {
    constructor() {
      super();
      this.a = a;
      this.b = b;
      this.delta = delta;
      this.scale = scale;
    }

    getPoint(t, optionalTarget = new THREE.Vector3()) {
      const { a, b, delta, scale } = this;
      return optionalTarget.set(
        scale * Math.sin(a * TAU * t + delta),
        scale * Math.sin(b * TAU * t),
        scale * Math.sin((a + b) * Math.PI * t)
      );
    }
  }

  return new LissajousCurve();
}

/**
 * Build a tube sculpture swept along the Lissajous curve.
 */
export function buildSculpture(params = {}) {
  const curve = lissajousCurve(params);
  const geometry = new THREE.TubeGeometry(curve, 256, 0.1, 8, true);
  const material = new THREE.MeshStandardMaterial();
  return new THREE.Mesh(geometry, material);
}
"})
