result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/lissajous.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { lissajousCurve, buildSculpture } from '../src/lissajous.js';

const EPS = 1e-9;

describe('lissajousCurve', () => {
  it('is closed for integer a and b (getPoint(0) coincides with getPoint(1))', () => {
    const cases = [
      { a: 1, b: 2 },
      { a: 3, b: 2, delta: Math.PI / 4 },
      { a: 5, b: 4, delta: Math.PI / 3 },
    ];
    for (const params of cases) {
      const curve = lissajousCurve(params);
      const p0 = curve.getPoint(0);
      const p1 = curve.getPoint(1);
      expect(p0.distanceTo(p1)).toBeLessThanOrEqual(EPS);
    }
  });

  it('keeps every sampled point within a Box3 of half-extent scale', () => {
    const scale = 2;
    const curve = lissajousCurve({ a: 3, b: 2, delta: Math.PI / 2, scale });
    const box = new THREE.Box3(
      new THREE.Vector3(-scale - EPS, -scale - EPS, -(scale + EPS)),
      new THREE.Vector3(scale + EPS, scale + EPS, scale + EPS)
    );
    for (let i = 0; i < 100; i++) {
      const t = i / 100;
      const p = curve.getPoint(t);
      expect(box.containsPoint(p), `point at t=${t} outside box: ${p.toArray().join(',')}`).toBe(true);
    }
  });

  it('produces a different polyline when a changes from 3 to 5', () => {
    const c1 = lissajousCurve({ a: 3, b: 2, delta: Math.PI / 2, scale: 1 });
    const c2 = lissajousCurve({ a: 5, b: 2, delta: Math.PI / 2, scale: 1 });

    const g1 = new THREE.TubeGeometry(c1, 256, 0.1, 8, true);
    const g2 = new THREE.TubeGeometry(c2, 256, 0.1, 8, true);

    // Compare sampled polylines directly as well.
    let differs = false;
    for (let i = 0; i <= 100; i++) {
      const t = i / 100;
      if (!c1.getPoint(t).equals(c2.getPoint(t))) {
        differs = true;
        break;
      }
    }
    expect(differs).toBe(true);
    expect(g1.attributes.position.array).not.toEqual(g2.attributes.position.array);
  });

  it('buildSculpture returns a Mesh with TubeGeometry', () => {
    const mesh = buildSculpture({ a: 3, b: 2, delta: Math.PI / 2, scale: 1 });
    expect(mesh).toBeInstanceOf(THREE.Mesh);
    expect(mesh.geometry).toBeInstanceOf(THREE.TubeGeometry);
    expect(mesh.geometry.tubularSegments).toBe(256);
    expect(mesh.geometry.radius).toBe(0.1);
    expect(mesh.geometry.radialSegments).toBe(8);
    expect(mesh.geometry.closed).toBe(true);
  });
});
"})
